#nullable enable // autogenerated

using System;
using PVZEngine.Tools.Cloning;

namespace MVZ2Logic
{
    [Serializable]
    public class SlowMotion : ICanClone
    {
        public SlowMotion(float timeout, float multiplier)
        {
            this.multiplier = multiplier;
            this.timeout = timeout;
        }
        public SlowMotion Clone()
        {
            return new SlowMotion(multiplier, timeout);
        }
        object ICanClone.Clone()
        {
            return Clone();
        }
        public float multiplier;
        public float timeout;
    }
}
